std::vector<int> v = {10, 20, 30};

// Classic Iterator Loop
for (auto it = v.begin(); it != v.end(); ++it) {
    *it *= 2;
}

// Range-based For Loop (Read/Write access)
for (int& x : v) {
    x += 1;
}

// Constant Iterator (Read-only)
for (auto cit = v.cbegin(); cit != v.cend(); ++cit) {
    // Read: *cit
}

